/* This file is #included by gzip.c */

import CMigration
import Darwin
import BZip2

fileprivate var inbuf = Array(repeating: UInt8(0), count: gzip.BUFLEN)
fileprivate var outbuf = Array(repeating: UInt8(0), count: gzip.BUFLEN)

extension gzip {

  func unbzip2(_ inx : FileDescriptor, _ out : FileDescriptor, _ pre : [UInt8]) -> (UInt, UInt)? {
    //	int		ret, end_of_file;

    var bytes_out : UInt = 0
    //	bz_stream	bzs;

    var cold = false

    var bzs = bz_stream()
    bzs.bzalloc = nil
    bzs.bzfree = nil
    bzs.opaque = nil

    var end_of_file = false

    var ret = BZ2_bzDecompressInit(&bzs, 0, 0)
    if ret != BZ_OK {
      maybe_errx("bzip2 init")
    }

    /* Prepend. */
    bzs.avail_in = UInt32(pre.count)
    bzs.next_in = pre;

    var bytes_in = UInt(pre.count)

    while ret == BZ_OK {
      check_siginfo()
      if bzs.avail_in == 0 && !end_of_file {
        guard let inbuf = try? inx.readUpToCount(Self.BUFLEN) else {
          maybe_err("read")
        }
        if inbuf.count == 0 {
          end_of_file = true
        }
        r.infile_current += UInt(inbuf.count)
        bzs.next_in = inbuf
        bzs.avail_in = UInt32(inbuf.count)
        if bytes_in != 0 {
          bytes_in += UInt(inbuf.count)
        }
      }

      bzs.next_out = outbuf
      bzs.avail_out = UInt32(Self.BUFLEN)
      ret = BZ2_bzDecompress(&bzs)

      switch ret {
        case BZ_STREAM_END, BZ_OK:
          if (ret == BZ_OK && end_of_file) {
            /*
             * If we hit this after a stream end, consider
             * it as the end of the whole file and don't
             * bail out.
             */
            if cold {
              ret = BZ_STREAM_END
            }
            else {
              maybe_errx("truncated file")
            }
          }
          cold = false
          if (!options.tflag && bzs.avail_out != Self.BUFLEN) {
            let n = write(out, outbuf, Self.BUFLEN - bzs.avail_out);
            if (n < 0) {
              maybe_err("write")
            }
            bytes_out += n
          }
          if (ret == BZ_STREAM_END && !end_of_file) {
            if (BZ2_bzDecompressEnd(&bzs) != BZ_OK ||
                BZ2_bzDecompressInit(&bzs, 0, 0) != BZ_OK) {
              maybe_errx("bzip2 re-init")
            }
            cold = true
            ret = BZ_OK
          }

        case BZ_DATA_ERROR:
          maybe_warnx("bzip2 data integrity error")

        case BZ_DATA_ERROR_MAGIC:
          maybe_warnx("bzip2 magic number error")

        case BZ_MEM_ERROR:
          maybe_warnx("bzip2 out of memory")

        default:
          maybe_warnx("unknown bzip2 error: %d", ret)
      }
    }

    if ret != BZ_STREAM_END || BZ2_bzDecompressEnd(&bzs) != BZ_OK {
      return nil
    }

    return (bytes_out, bytes_in)
  }

